export const MONUMENTS = JSON.parse("[{\"id\":\"n249082841\",\"kind\":\"monument\",\"sub\":\"statue\",\"name\":\"Петру Великому\",\"x\":-2745.5,\"z\":-444.2,\"material\":\"bronze\",\"inscription\":\"ПЕТРУ перьвому ЕКАТЕРИНА вторая лѣта 1782.\",\"wikidata\":\"Q672444\",\"wikipedia\":\"ru:Медный всадник\"},{\"id\":\"n1191476119\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Древнеегипетский сфинкс\",\"x\":-3397.4,\"z\":-497,\"startDate\":\"C14 BC\",\"wikidata\":\"Q2657856\",\"wikipedia\":\"ru:Сфинксы на Университетской набережной\"},{\"id\":\"n1191476126\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Древнеегипетский сфинкс\",\"x\":-3360.5,\"z\":-518.7,\"startDate\":\"C14 BC\",\"wikidata\":\"Q2657856\",\"wikipedia\":\"ru:Сфинксы на Университетской набережной\"},{\"id\":\"n2586283111\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Д. Трезини\",\"x\":-3532.3,\"z\":-486.5,\"wikidata\":\"Q25395360\",\"wikipedia\":\"ru:Памятник Трезини (Санкт-Петербург)\"},{\"id\":\"n6419451604\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. К. Рериху\",\"x\":-3588.5,\"z\":-471.5,\"subject\":\"Q208993\",\"inscription\":\"В этом доме родился и жил с 1874 по 1899 год мыслитель-гуманист, художник Николай Рерих\"},{\"id\":\"n7683216131\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. А. Стеклову\",\"x\":-3649.4,\"z\":-453.2,\"subject\":\"Q559188\",\"inscription\":\"Здесь жил академик Владимир Андреевич Стеклов, 1863–1926, выдающийся математик\"},{\"id\":\"n7683216132\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Б. С. Якоби\",\"x\":-3652.3,\"z\":-451.6,\"subject\":\"Q60579\",\"inscription\":\"Здесь жил академик Борис Семенович Якоби, 1801–1874. Выдающийся физик и электротехник. Изобретатель гальванопластики, электрического телеграфа, электрических моторных лодок, электрических мин.\"},{\"id\":\"n7683216133\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. П. Карпинскому\",\"x\":-3655.2,\"z\":-450,\"subject\":\"Q729563\",\"inscription\":\"Здесь жил с 1899 г. по 1935 г. Президент Академии Наук СССР Александр Петрович Карпинский, знаменитый геолог, «отец русской геологии», 1847–1936\"},{\"id\":\"n7683216134\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. Ю. Крачковскому\",\"x\":-3661.2,\"z\":-446.6,\"subject\":\"Q1996028\",\"inscription\":\"В этом доме жил и умер выдающийся советский ученый-востоковед, крупнейший деятель русской арабистики, академик Игнатий Юлианович Крачковский (1883–1951 гг.)\"},{\"id\":\"n7685081681\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. П. Васильеву\",\"x\":-3661.5,\"z\":-447,\"subject\":\"Q721077\",\"inscription\":\"Здесь жил академик Василий Павлович Васильев, 1818–1900. Крупнейший русский китаевед.\"},{\"id\":\"n7685081682\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Вернадскому\",\"x\":-3655.5,\"z\":-450.5,\"subject\":\"Q316371\",\"inscription\":\"Здесь жил академик Владимир Иванович Вернадский, 1863–1945. Знаменитый геолог и минералог. Основоположник науки о химии земли.\"},{\"id\":\"n7685081683\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. В. Петрову\",\"x\":-3652.6,\"z\":-452.1,\"subject\":\"Q2721074\",\"inscription\":\"Здесь жил академик Василий Владимирович Петров, 1761–1834. Выдающийся физик и химик, изобретатель электрической дуги.\"},{\"id\":\"n7685081684\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. П. Павлову\",\"x\":-3649.7,\"z\":-453.8,\"subject\":\"Q42985\",\"inscription\":\"Здесь жил и умер великий русский физиолог Иван Петрович Павлов, 1849–1936\"},{\"id\":\"n7688151085\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. М. Ляпунову\",\"x\":-3648.7,\"z\":-455.4,\"subject\":\"Q310788\",\"inscription\":\"Здесь жил академик Александр Михайлович Ляпунов, 1857–1918. Знаменитый математик, создатель общей теории устойчивости и теории фигур небесных тел.\"},{\"id\":\"n7688151086\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. А. Борисяку\",\"x\":-3650.4,\"z\":-458.5,\"subject\":\"Q4094072\",\"inscription\":\"Здесь жил академик Алексей Алексеевич Борисяк, 1872–1944. Выдающийся палеонтолог.\"},{\"id\":\"n7688151087\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Я. К. Гроту\",\"x\":-3652.2,\"z\":-461.5,\"subject\":\"Q2995186\",\"inscription\":\"Здесь жил академик Яков Карлович Грот, 1812–1893. Преобразователь русской орфографии и составитель «Словаря русского языка».\"},{\"id\":\"n7688151088\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. Ф. Ольденбургу\",\"x\":-3653.9,\"z\":-464.5,\"subject\":\"Q171848\",\"inscription\":\"Здесь жил академик Сергей Федорович Ольденбург, 1863–1934. Выдающийся индолог.\"},{\"id\":\"n7688151089\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. О. Ковалевскому\",\"x\":-3655.6,\"z\":-467.5,\"subject\":\"Q560321\",\"inscription\":\"В этом доме жил с 1892 по 1901 год академик Александр Онуфриевич Ковалевский, выдающийся русский зоолог и эмбриолог.\"},{\"id\":\"n7688151090\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ф. Ю. Левинсону-Лессингу\",\"x\":-3655.2,\"z\":-467.8,\"subject\":\"Q1396733\",\"inscription\":\"Выдающийся русский петрограф, академик Франц Юльевич Левинсон-Лессинг жил в этом доме с 1929 г. по 1939 г.\"},{\"id\":\"n7688151091\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ф. И. Успенскому\",\"x\":-3653.5,\"z\":-464.7,\"subject\":\"Q451292\",\"inscription\":\"Здесь жил академик Федор Иванович Успенский, 1845–1928. Знаменитый русский византолог.\"},{\"id\":\"n7688151092\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. С. Орлову\",\"x\":-3651.8,\"z\":-461.7,\"subject\":\"Q4336606\",\"inscription\":\"Здесь жил академик Александр Сергеевич Орлов, 1871–1947. Выдающийся исследователь русской литературы.\"},{\"id\":\"n7688151093\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. С. Фаминцыну\",\"x\":-3650.1,\"z\":-458.6,\"subject\":\"Q2067228\",\"inscription\":\"Здесь жил академик Андрей Сергеевич Фаминцын. 1835–1918. Выдающийся ботаник.\"},{\"id\":\"n7688151094\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. А. Маркову\",\"x\":-3648.4,\"z\":-455.6,\"subject\":\"Q176659\",\"inscription\":\"Здесь жил академик Андрей Андреевич Марков, 1856–1922. Выдающийся математик, широко известный своими работами по теории чисел и теории вероятностей.\"},{\"id\":\"n7688189766\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. И. Шёгрену\",\"x\":-3669.9,\"z\":-493.9,\"subject\":\"Q1394543\",\"inscription\":\"Здесь с 1833 по 1855 год жил российский академик Андреас Иоган Шёгрен, выдающийся исследователь истории, языка и культуры Финляндии и финно-угорских народов\"},{\"id\":\"n7688189768\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. Я. Марру\",\"x\":-3661.7,\"z\":-478.1,\"subject\":\"Q116309\",\"inscription\":\"Здесь жил с 1918 г. по 1964 г. академик Николай Яковлевич Марр. Выдающийся археолог и языковед, 1864–1934\"},{\"id\":\"n7688189769\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. М. Алексееву\",\"x\":-3663.3,\"z\":-481.1,\"subject\":\"Q921322\",\"inscription\":\"Здесь жил с 1939 по 1951 год академик Василий Михайлович Алексеев — крупнейший советский исследователь литературы, языка и культуры Китая\"},{\"id\":\"n7688189770\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. С. Бушмину\",\"x\":-3662.8,\"z\":-481.3,\"subject\":\"Q4100687\",\"inscription\":\"В этом доме с 1966 по 1983 год жил и работал крупный советский литературовед, академик Алексей Сергеевич Бушмин\"},{\"id\":\"n7688189771\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. А. Зернову\",\"x\":-3661.2,\"z\":-478.4,\"subject\":\"Q4191600\",\"inscription\":\"Здесь жил с 1931 года и скончался выдающийся гидробиолог, академик Сергей Алексеевич Зернов, 1871–1945\"},{\"id\":\"n8089429889\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"А. П. Карпинский\",\"x\":-4974.1,\"z\":-503.2,\"subject\":\"Q729563\"}]");
